<script setup lang="ts">
import { computed,onMounted,ref } from 'vue'; import { getOperationLogs,getSystemLogs } from '../../api/modules/settings'; import type { OperationLog,SystemLog } from '../../types/settings'
const props=defineProps<{kind:'operation'|'system'}>(); const operations=ref<OperationLog[]>([]),systems=ref<SystemLog[]>([]),query=ref(''),filter=ref('全部'),selected=ref<OperationLog|SystemLog|null>(null)
const rows=computed(()=>props.kind==='operation'?operations.value.filter(row=>(filter.value==='全部'||row.module===filter.value)&&(!query.value||Object.values(row).join('').toLowerCase().includes(query.value.toLowerCase()))):systems.value.filter(row=>(filter.value==='全部'||row.level===filter.value)&&(!query.value||Object.values(row).join('').toLowerCase().includes(query.value.toLowerCase()))));onMounted(async()=>{if(props.kind==='operation')operations.value=await getOperationLogs();else systems.value=await getSystemLogs()})
</script>
<template><section class="settings-page"><header class="settings-page__header"><div><p class="page-eyebrow">{{kind==='operation'?'OPERATION AUDIT':'SYSTEM DIAGNOSTICS'}}</p><h1>{{kind==='operation'?'操作日志':'系统日志'}}</h1></div><button class="settings-secondary">下载筛选结果</button></header><div class="settings-toolbar"><label><span>⌕</span><input v-model="query" :placeholder="kind==='operation'?'搜索用户、对象或操作':'搜索日志或 Trace ID'"></label><div><select v-model="filter"><option>全部</option><template v-if="kind==='operation'"><option>任务管理</option><option>实时监控</option><option>地图管理</option><option>行为树管理</option><option>资源管理</option></template><template v-else><option>INFO</option><option>WARN</option><option>ERROR</option></template></select><select><option>最近 1 小时</option><option>今天</option><option>最近 7 天</option></select></div></div><div class="settings-table-wrap"><table v-if="kind==='operation'" class="settings-table log-table"><thead><tr><th>时间</th><th>用户</th><th>模块</th><th>操作</th><th>对象</th><th>结果</th><th>说明</th><th></th></tr></thead><tbody><tr v-for="row in rows as OperationLog[]" :key="`${row.time}-${row.object}`" @click="selected=row"><td class="type-data muted-cell">{{row.time}}</td><td class="settings-id">{{row.user}}</td><td>{{row.module}}</td><td>{{row.action}}</td><td>{{row.object}}</td><td><span class="asset-status success">{{row.result}}</span></td><td>{{row.description}}</td><td><button class="table-action">查看</button></td></tr></tbody></table><table v-else class="settings-table log-table"><thead><tr><th>时间</th><th>级别</th><th>服务</th><th>AMR</th><th>任务</th><th>Trace ID</th><th>日志摘要</th><th></th></tr></thead><tbody><tr v-for="row in rows as SystemLog[]" :key="row.traceId" @click="selected=row"><td class="type-data muted-cell">{{row.time}}</td><td><span class="log-level" :class="row.level.toLowerCase()">{{row.level}}</span></td><td>{{row.service}}</td><td>{{row.amr}}</td><td>{{row.task}}</td><td class="type-data settings-id">{{row.traceId}}</td><td>{{row.summary}}</td><td><button class="table-action">查看</button></td></tr></tbody></table></div><div v-if="selected" class="settings-drawer-backdrop" @click.self="selected=null"><aside class="log-detail-drawer"><header><div><small>{{kind==='operation'?'AUDIT DETAIL':'LOG DETAIL'}}</small><strong>{{kind==='operation'?'操作详情':'系统日志详情'}}</strong></div><button @click="selected=null">×</button></header><dl><div v-for="(value,key) in selected" :key="key"><dt>{{key}}</dt><dd>{{value}}</dd></div></dl><footer v-if="kind==='system'"><button>复制 Trace ID</button><button class="primary" @click="selected=null">关闭</button></footer><footer v-else><button class="primary" @click="selected=null">关闭</button></footer></aside></div></section></template>
